type AnalysisStatus = "idle" | "queued" | "processing" | "failed" | "completed";
type AnalysisStage<T> = { status:AnalysisStatus; data?:T; error?:string; progress?:number; updatedAt?:string };
type CharacterResult = { id:number; name:string; role?:string; aliases?:string[]; episodes:number[]; confidence?:number; evidence?:string[]; relationships?:{ targetId:number; label:string; episode?:number; evidence?:string }[] };
type StoryResult = { episode:number; title?:string; summary:string; coreEvents?:string[]; relationshipChanges?:string[]; emotions?:{ label:string; score:number }[]; foreshadowing?:string[]; editSuggestion?:{ start:number; end:number; reason:string } };
type HighlightResult = { id:number; category:string; episode:number; start:number; end:number; title:string; emotion?:string; event?:string; retention?:number; spoilerRisk?:string; setup?:string; cut?:string; evidence?:string };
type RangeResult = { id:number; episodeStart:number; episodeEnd:number; start:number; end:number; title:string; summary:string; characterIds?:number[]; continuity?:number; editability?:number; modes:string[]; paywall?:string };
type DramaAnalysis = { characters?:AnalysisStage<CharacterResult[]>; story?:AnalysisStage<StoryResult[]>; highlights?:AnalysisStage<HighlightResult[]>; ranges?:AnalysisStage<RangeResult[]> };
type Drama = { id:number; pocketbaseId?:string; title:string; cn:string; genre:string; language:string; episodes:number; freeEpisodes:number; state:ParseState; color:string; people:number; ranges:number; highlights:number; drafts:number; factoryUses:number; parse:ParseTier[]; poster?:string; availableEpisodes?:number[]; episodeMedia?:Record<number,FactoryEpisodeMedia>; analysis?:DramaAnalysis };
type ImportForm = { title:string; cn:string; genre:string; language:string; episodes:string; freeEpisodes:string; copyright:string; coarse:string; detail:string; precision:string; poster:string; uploadedEpisodes:number[]; videoFiles?:{file:File;episode:number}[] };
type RecognizedEpisodeFile = { name:string; episode:number; recognized:boolean };

function recognizeEpisodeFiles(names:string[],fallbackStart:number):RecognizedEpisodeFile[] {
  const used=new Set<number>();
  return names.map((name,index)=>{
    const stem=name.replace(/\.[^.]+$/,"").replace(/[（）]/g,match=>match==="（"?"(":")").trim();
    const duplicate=stem.match(/^(.*?)[\s_-]*\((\d+)\)$/);const base=(duplicate?.[1]??stem).trim();const duplicateIndex=duplicate?Number(duplicate[2]):1;
    const tagged=base.match(/(?:^|[^a-z0-9])(?:ep(?:isode)?|e)\s*[-_ ]*0*(\d+)(?:\D|$)/i)??base.match(/第\s*0*(\d+)\s*集/);
    const plain=base.match(/(?:^|\D)0*(\d+)(?:\D|$)/);let episode=Number(tagged?.[1]??plain?.[1]??0);const recognized=episode>0;
    if(recognized&&duplicateIndex>1)episode+=duplicateIndex-1;if(!recognized)episode=fallbackStart+index;while(used.has(episode))episode+=1;used.add(episode);
    return {name,episode,recognized};
  }).sort((a,b)=>a.episode-b.episode);
}

const initialDramas: Drama[] = [];
const fallbackAvailableEpisodes = (_drama:Drama) => [];

const DRAMA_STORAGE_KEY = "lumina.drama-library.v1";
const supportedDramaFile = (name:string) => ["mp4","mov"].includes(name.split(".").pop()?.toLowerCase()??"");
const supportedPosterType = (file:File) => ["image/jpeg","image/png","image/webp"].includes(file.type);
const preparePoster = (file:File):Promise<string> => new Promise((resolve,reject)=>{
  if(!supportedPosterType(file)){reject(new Error("仅支持 JPG、PNG 或 WebP 海报"));return}
  if(file.size>8*1024*1024){reject(new Error("海报文件不能超过 8MB"));return}
  const reader=new FileReader();reader.onerror=()=>reject(new Error("海报读取失败，请重新选择"));reader.onload=()=>{const image=new Image();image.onerror=()=>reject(new Error("无法识别该图片"));image.onload=()=>{const maxWidth=900;const maxHeight=1200;const scale=Math.min(1,maxWidth/image.width,maxHeight/image.height);const canvas=document.createElement("canvas");canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));const context=canvas.getContext("2d");if(!context){reject(new Error("海报处理失败"));return}context.drawImage(image,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL("image/jpeg",.82))};image.src=String(reader.result)};reader.readAsDataURL(file)
});
const mergeStoredDramas = (stored:unknown):Drama[] => {
  if(!Array.isArray(stored)) return initialDramas;
  const valid=stored.filter((item):item is Drama=>Boolean(item&&typeof item==="object"&&typeof (item as Drama).id==="number"&&typeof (item as Drama).title==="string"&&Array.isArray((item as Drama).parse))).filter(item=>![1,2,3,4].includes(item.id)).map(item=>({...item,availableEpisodes:Array.isArray(item.availableEpisodes)?item.availableEpisodes:fallbackAvailableEpisodes(item)}));
  const storedKeys=new Set(valid.flatMap(item=>[String(item.id),item.title.trim().toLowerCase(),item.cn.trim().toLowerCase()]));
  return [...valid,...initialDramas.filter(item=>![String(item.id),item.title.trim().toLowerCase(),item.cn.trim().toLowerCase()].some(key=>storedKeys.has(key)))];
};

