function dramaFromPocketBaseLegacy(record:PocketBaseDramaRecord):Drama {
  const parseConfig=(record.parseConfig??{}) as {coarse?:string;detail?:string;precision?:string};
  const rawAnalysis=(record.analysis&&typeof record.analysis==="object"?record.analysis:{}) as Record<string,AnalysisStage<unknown>>;
  const normalizeStage=<T,>(stage:AnalysisStage<T>|undefined):AnalysisStage<T>|undefined=>{if(!stage)return undefined;const raw=String(stage.status);const status:AnalysisStatus=raw==="running"?"processing":raw==="pending"?"queued":raw==="done"||raw==="success"?"completed":raw==="error"?"failed":(["idle","queued","processing","failed","completed"].includes(raw)?raw:"idle") as AnalysisStatus;return {...stage,status}};
  const analysis:DramaAnalysis={characters:normalizeStage(rawAnalysis.characters as AnalysisStage<CharacterResult[]>),story:normalizeStage(rawAnalysis.story as AnalysisStage<StoryResult[]>),highlights:normalizeStage(rawAnalysis.highlights as AnalysisStage<HighlightResult[]>),ranges:normalizeStage(rawAnalysis.ranges as AnalysisStage<RangeResult[]>)};
  const state:ParseState=record.parseState==="completed"?"解析完成":record.parseState==="running"?"解析中":record.parseState==="failed"?"解析失败":"待解析";
  const media=Object.values(record.episodeMedia);const completed=media.filter(item=>item.analysisStatus==="completed").length;const running=media.filter(item=>item.analysisStatus==="running"||item.analysisStatus==="processing");const coarseProgress=media.length?Math.round(media.reduce((sum,item)=>sum+(item.analysisStatus==="completed"?100:item.analysisProgress??0),0)/media.length):0;
  const resultProgress=(stages:(AnalysisStage<unknown>|undefined)[])=>stages.length?Math.round(stages.reduce((sum,item)=>sum+(item?.status==="completed"?100:item?.progress??0),0)/stages.length):0;
  const fineStages=[analysis.characters,analysis.story];const precisionStages=[analysis.highlights,analysis.ranges];
  return {id:Number(record.externalId),pocketbaseId:record.recordId,title:record.title,cn:record.cn,genre:record.genre,language:record.language,episodes:record.totalEpisodes,freeEpisodes:record.freeEpisodes,state,color:"#0284c7",people:analysis.characters?.data?.length??0,ranges:analysis.ranges?.data?.length??0,highlights:analysis.highlights?.data?.length??0,drafts:0,factoryUses:0,poster:record.posterUrl,availableEpisodes:Object.keys(record.episodeMedia).map(Number),episodeMedia:record.episodeMedia,analysis,parse:[{label:"粗解析",short:"粗",progress:coarseProgress,scope:media.length?`${completed}/${media.length} 集完成${running.length?` · ${running.length} 集处理中`:""}`:"暂无片源"},{label:"重点集细解析",short:"细",progress:resultProgress(fineStages),scope:parseConfig.detail?`配置集数 ${parseConfig.detail}`:"未配置重点集"},{label:"高光区间精解析",short:"精",progress:resultProgress(precisionStages),scope:parseConfig.precision??"未配置精解析"}]};
}

function dramaFromPocketBase(record:PocketBaseDramaRecord):Drama {
  const config=(record.parseConfig??{}) as {detail?:string;precision?:string};
  const unwrap=(value:unknown):Record<string,unknown>=>{if(!value||typeof value!=="object")return {};const object=value as Record<string,unknown>;return object.result&&typeof object.result==="object"?object.result as Record<string,unknown>:object};
  const list=(value:unknown):Record<string,unknown>[]=>Array.isArray(value)?value.filter(item=>item&&typeof item==="object") as Record<string,unknown>[]:[];
  const num=(value:unknown,fallback=0)=>Number.isFinite(Number(value))?Number(value):fallback;
  const textValue=(value:unknown)=>{if(typeof value==="string")return value;if(!value||typeof value!=="object")return "";const object=value as Record<string,unknown>;return String(object.text??object.value??object.reason??object.description??"")};
  const stageStatus=(value:string):AnalysisStatus=>value==="succeeded"||value==="completed"||value==="success"||value==="done"?"completed":value==="running"||value==="processing"?"processing":value==="failed"||value==="error"?"failed":value==="queued"||value==="pending"?"queued":"idle";
  const evidenceText=(value:unknown)=>list(value).map(item=>{const time=(item.timecode??{}) as Record<string,unknown>;return `${item.episode?`第 ${item.episode} 集 · `:""}${num(time.start).toFixed(2)}-${num(time.end).toFixed(2)} 秒 · ${String(item.text??item.description??"")}`.trim()}).filter(Boolean);
  const detail=unwrap(record.detailResult??record.analysis);
  const rawCharacters=list(detail.characters);const rawRelations=list(detail.relationships);
  const nameIds=new Map(rawCharacters.map((item,index)=>[String(item.name||`人物 ${index+1}`),index+1]));
  const characters:CharacterResult[]=rawCharacters.map((item,index)=>{const name=String(item.name||`人物 ${index+1}`);const evidence=list(item.evidence);const episodes=[...new Set(evidence.map(value=>num(value.episode)).filter(Boolean))];const relationships=rawRelations.filter(value=>{if(Array.isArray(value.pair))return (value.pair as unknown[]).map(String).includes(name);return [String(value.from??""),String(value.to??"")].includes(name)}).map(value=>{const pair=Array.isArray(value.pair)?(value.pair as unknown[]).map(String):[String(value.from??""),String(value.to??"")];const target=pair.find(valueName=>valueName!==name)||"";return {targetId:nameIds.get(target)||0,label:String(value.type??value.status??"关系"),evidence:String(value.description??value.dynamics??""),episode:num((list(value.evidence)[0]??{}).episode)||undefined}});return {id:index+1,name,role:String(item.role??item.description??"")||undefined,aliases:Array.isArray(item.aliases)?item.aliases.map(String):undefined,episodes,confidence:evidence.length?Math.round(evidence.reduce((sum,value)=>sum+num(value.confidence),0)/evidence.length*100):undefined,evidence:evidenceText(item.evidence),relationships}});
  const story:StoryResult[]=list(detail.episodePlots).map(item=>({episode:num(item.episode),title:String(item.title??"")||undefined,summary:String(item.summary??""),coreEvents:list(item.keyEvents).map(value=>String(value.description??"")).filter(Boolean)}));
  const candidates=list(detail.highlightCandidates);
  const parsedPrecision=record.precisionResults.map((entry,index)=>{const result=unwrap(entry.result);const interval=(result.interval??{}) as Record<string,unknown>;const start=num(interval.start);const end=num(interval.end);const candidate=candidates.find(item=>num(item.episode)===entry.episode&&Math.abs(num(item.start)-start)<.2&&Math.abs(num(item.end)-end)<.2);const analysis=(result.highlight_analysis??{}) as Record<string,unknown>;const scores=(analysis.explainable_highlight_scores??{}) as Record<string,unknown>;const scoreValues=Object.entries(scores).filter(([key,value])=>key.endsWith("_score")&&Number.isFinite(Number(value))).map(([,value])=>Number(value));const score=scoreValues.length?Math.round(scoreValues.reduce((sum,value)=>sum+value,0)/scoreValues.length*10):undefined;const candidateEvidence=list(candidate?.evidence);const shot=(analysis.shot_semantics??{}) as Record<string,unknown>;const rhythm=(analysis.audio_visual_rhythm??{}) as Record<string,unknown>;return {id:index+1,episode:entry.episode,start,end,title:String(candidateEvidence[0]?.text??`第 ${entry.episode} 集 ${start.toFixed(2)}-${end.toFixed(2)} 秒`),category:"精解析高光",emotion:textValue(rhythm.tempo)||undefined,event:textValue(scores.justification)||undefined,retention:score,evidence:textValue(shot.primary_shot)||String(candidateEvidence[0]?.text??"")||undefined}}).filter(item=>item.episode>0&&item.end>item.start);
  const highlights:HighlightResult[]=parsedPrecision;
  const ranges:RangeResult[]=parsedPrecision.map(item=>({id:item.id,episodeStart:item.episode,episodeEnd:item.episode,start:item.start,end:item.end,title:item.title,summary:item.event??item.evidence??"已通过精解析验证",continuity:item.retention,editability:item.retention,modes:["真实片源区间"]}));
  const detailState=stageStatus(record.detailStatus);const precisionState=stageStatus(record.precisionStatus);
  const analysis:DramaAnalysis={characters:{status:detailState,data:detailState==="completed"?characters:undefined,error:detailState==="failed"?record.analysisError:undefined,progress:record.detailProgress},story:{status:detailState,data:detailState==="completed"?story:undefined,error:detailState==="failed"?record.analysisError:undefined,progress:record.detailProgress},highlights:{status:precisionState,data:precisionState==="completed"?highlights:undefined,error:precisionState==="failed"?record.analysisError:undefined,progress:record.precisionProgress},ranges:{status:precisionState,data:precisionState==="completed"?ranges:undefined,error:precisionState==="failed"?record.analysisError:undefined,progress:record.precisionProgress}};
  const states=[record.coarseStatus,record.detailStatus,record.precisionStatus].map(stageStatus);const state=(states.every(value=>value==="completed")?"解析完成":states.some(value=>value==="failed")?"解析失败":states.some(value=>value==="processing")?"解析中":"待解析") as ParseState;
  const media=Object.values(record.episodeMedia);const completed=media.filter(item=>item.analysisStatus==="completed").length;const running=media.filter(item=>item.analysisStatus==="running"||item.analysisStatus==="processing").length;
  return {id:Number(record.externalId),pocketbaseId:record.recordId,title:record.title,cn:record.cn,genre:record.genre,language:record.language,episodes:record.totalEpisodes,freeEpisodes:record.freeEpisodes,state,color:"#0284c7",people:characters.length,ranges:ranges.length,highlights:highlights.length,drafts:0,factoryUses:0,poster:record.posterUrl,availableEpisodes:Object.keys(record.episodeMedia).map(Number),episodeMedia:record.episodeMedia,analysis,parse:[{label:"粗解析",short:"粗",progress:record.coarseProgress,scope:media.length?`${completed}/${media.length} 集完成${running?` · ${running} 集处理中`:""}`:"暂无片源"},{label:"重点集细解析",short:"细",progress:record.detailProgress,scope:detailState==="completed"?`${story.length} 集剧情 · ${characters.length} 个人物`:config.detail?`配置集数 ${config.detail}`:"未配置重点集"},{label:"高光区间精解析",short:"精",progress:record.precisionProgress,scope:precisionState==="completed"?`${highlights.length} 个候选区间已验证`:config.precision??"未配置精解析"}]};
}

async function migrateLegacyDramasToPocketBase() {
  const raw=window.localStorage.getItem(DRAMA_STORAGE_KEY);
  if(!raw)return [] as PocketBaseDramaRecord[];
  const legacy=mergeStoredDramas(JSON.parse(raw));
  const migrated:PocketBaseDramaRecord[]=[];
  for(const drama of legacy){
    const media=await listEpisodeMedia(drama.id);
    if(!media.length)continue;
    migrated.push(await saveDramaToPocketBase({externalId:String(drama.id),title:drama.title,cn:drama.cn,genre:drama.genre,language:drama.language,totalEpisodes:drama.episodes,freeEpisodes:drama.freeEpisodes,copyrightStatus:"历史本地导入",posterDataUrl:drama.poster?.startsWith("data:")?drama.poster:undefined,parseConfig:{coarse:drama.freeEpisodes,detail:"1-5",precision:"自动发现候选"},episodes:media.map(item=>({episode:item.episode,file:new File([item.blob],item.name,{type:item.mimeType})}))}));
  }
  return migrated;
}

function Progress({tier,color}:{tier:ParseTier;color:string}) { return <div className={styles.progressRow}><span className={styles.tierDot} style={{"--tier-color":color} as CSSProperties}>{tier.short}</span><div><b>{tier.label}</b><small>{tier.scope}</small></div><div className={styles.progressTrack}><i style={{width:`${tier.progress}%`,background:color}} /></div><strong>{tier.progress}%</strong></div>; }
function Metric({label,value,hint}:{label:string;value:string|number;hint?:string}) { return <div className={styles.metric}><small>{label}</small><b>{value}</b>{hint&&<span>{hint}</span>}</div>; }
function StateView({kind,onRetry}:{kind:"loading"|"empty"|"error";onRetry?:()=>void}) { return <div className={styles.stateView}><div>{kind==="loading"?<span className={styles.spinner}/>:kind==="error"?"!":"◇"}</div><h3>{kind==="loading"?"正在读取剧库…":kind==="error"?"数据加载失败":"没有符合条件的短剧"}</h3><p>{kind==="empty"?"调整筛选条件，或导入一部新的短剧。":kind==="error"?"网络波动导致本次请求失败，请重新加载。":"正在同步剧集、解析进度与生产资产。"}</p>{onRetry&&<button onClick={onRetry}>重新加载</button>}</div>; }

