export type DramaLibraryWorkspaceProps = { onEnterFactory?:(payload:{dramaId:number;mode:string;sourceId?:number;title:string;cn:string;genre:string;language:string;episodes:number;freeEpisodes:number;availableEpisodes:number[];episodeMedia:Record<number,FactoryEpisodeMedia>})=>void; onImportDrama?:()=>void; onCreateParsingTask?:(task:ParsingTaskInput)=>void; onOpenProductionRecord?:(title:string)=>void; onRetryAnalysis?:(dramaId:number,stage:keyof DramaAnalysis)=>void; onPersistAnalysis?:(dramaId:number,stage:keyof DramaAnalysis,data:unknown)=>void; onPreviewSource?:(payload:{dramaId:number;episode:number;start?:number;end?:number})=>void };

export function DramaLibraryWorkspace({onEnterFactory,onImportDrama,onCreateParsingTask,onOpenProductionRecord,onRetryAnalysis:externalRetryAnalysis,onPersistAnalysis:externalPersistAnalysis,onPreviewSource:externalPreviewSource}:DramaLibraryWorkspaceProps) {
  const [dramas,setDramas]=useState(initialDramas); const [selected,setSelected]=useState<Drama|null>(null); const [tab,setTab]=useState<DetailTab>("overview");
  const [query,setQuery]=useState(""); const [genre,setGenre]=useState("全部题材"); const [language,setLanguage]=useState("全部语种"); const [parseState,setParseState]=useState("全部状态");
  const [highlightType,setHighlightType]=useState("全部类型"); const [toast,setToast]=useState(""); const [activeEpisode,setActiveEpisode]=useState(3);
  const [importOpen,setImportOpen]=useState(false); const [parseOpen,setParseOpen]=useState(false); const [listState,setListState]=useState<"ready"|"loading"|"error">("ready");
  const posterInput=useRef<HTMLInputElement>(null);
  const [storageReady,setStorageReady]=useState(false);
  const [episodeMedia,setEpisodeMedia]=useState<Record<number,FactoryEpisodeMedia>>({});
  useEffect(()=>{let cancelled=false;setListState("loading");void (async()=>{try{let records=await listPocketBaseDramas();if(records.length===0)records=await migrateLegacyDramasToPocketBase();if(cancelled)return;setDramas(records.map(dramaFromPocketBase));setListState("ready");setStorageReady(true)}catch(error){console.error("PocketBase drama migration failed",error);if(cancelled)return;let restored=initialDramas;try{const raw=window.localStorage.getItem(DRAMA_STORAGE_KEY);if(raw)restored=mergeStoredDramas(JSON.parse(raw))}catch{/* 损坏的缓存不阻断错误提示 */}setDramas(restored);setListState(restored.length?"ready":"error");setStorageReady(true)}})();return()=>{cancelled=true}},[]);
  useEffect(()=>{if(!storageReady)return;try{window.localStorage.setItem(DRAMA_STORAGE_KEY,JSON.stringify(dramas))}catch{/* 隐私模式或容量不足时继续使用会话内状态 */}},[dramas,storageReady]);
  useEffect(()=>{if(!storageReady)return;const builtInIds=new Set(initialDramas.map(item=>item.id));dramas.filter(item=>item.state==="解析中"&&!builtInIds.has(item.id)).forEach(item=>onCreateParsingTask?.({id:`PARSE-${item.id}`,title:`${item.title} · 三级解析`,status:"处理中",progress:Math.max(...item.parse.map(tier=>tier.progress)),cost:"解析资源计算中"}))},[dramas,storageReady,onCreateParsingTask]);
  useEffect(()=>{setEpisodeMedia(selected?.episodeMedia??{})},[selected]);
  useEffect(()=>{if(!selected||!onOpenProductionRecord)return;const records=Array.from(document.querySelectorAll(`.${styles.activity} > div`));const cleanups=records.map(record=>{const element=record as HTMLElement;element.tabIndex=0;element.setAttribute("role","button");element.setAttribute("aria-label",`打开创作记录：${element.querySelector("b")?.textContent??"生产记录"}`);const open=()=>onOpenProductionRecord(element.querySelector("b")?.textContent??"生产记录");const click=()=>open();const keydown=(event:Event)=>{const keyboardEvent=event as KeyboardEvent;if(keyboardEvent.key==="Enter"||keyboardEvent.key===" "){keyboardEvent.preventDefault();open()}};element.addEventListener("click",click);element.addEventListener("keydown",keydown);return()=>{element.removeEventListener("click",click);element.removeEventListener("keydown",keydown)}});return()=>cleanups.forEach(cleanup=>cleanup())},[selected,onOpenProductionRecord]);
  const notify=(message:string)=>{setToast(message);window.setTimeout(()=>setToast(""),2300)};
  const filtered=useMemo(()=>dramas.filter(d=>{const term=query.trim().toLowerCase();return(!term||`${d.title}${d.cn}${d.genre}${d.language}`.toLowerCase().includes(term))&&(genre==="全部题材"||d.genre===genre)&&(language==="全部语种"||d.language.includes(language))&&(parseState==="全部状态"||d.state===parseState)}),[dramas,query,genre,language,parseState]);
  const highlightResults=selected?.analysis?.highlights?.data??[];
  const visibleHighlights=highlightType==="全部类型"?highlightResults:highlightResults.filter(h=>h.category===highlightType);
  const refresh=()=>{setListState("loading");void listPocketBaseDramas().then(records=>{const next=records.map(dramaFromPocketBase);setDramas(next);setSelected(current=>current?next.find(item=>item.id===current.id)??null:current);setListState("ready")}).catch(()=>setListState(dramas.length?"ready":"error"))};
  const openImport=()=>{setImportOpen(true);onImportDrama?.()};
  const enterFactory=(mode:string,sourceId?:number)=>{if(selected)onEnterFactory?.({dramaId:selected.id,mode,sourceId,title:selected.title,cn:selected.cn,genre:selected.genre,language:selected.language,episodes:selected.episodes,freeEpisodes:selected.freeEpisodes,availableEpisodes:Object.keys(episodeMedia).map(Number),episodeMedia});notify(`已将「${selected?.cn??"短剧"}」及真实可用片源带入${mode}`)};
  const finishImport=async(form:ImportForm)=>{const episodes=Number(form.episodes)||1;const free=Number(form.freeEpisodes)||Math.min(15,episodes);const externalId=String(Date.now());try{const stored=await saveDramaToPocketBase({externalId,title:form.title||"Untitled Drama",cn:form.cn||"未命名短剧",genre:form.genre,language:form.language,totalEpisodes:episodes,freeEpisodes:free,copyrightStatus:form.copyright,posterDataUrl:form.poster||undefined,parseConfig:{coarse:form.coarse,detail:form.detail,precision:form.precision},episodes:form.videoFiles??[]});const item=dramaFromPocketBase(stored);setDramas(v=>[item,...v.filter(value=>value.id!==item.id)]);onCreateParsingTask?.({id:`PARSE-${item.id}`,title:`${item.title} · 三级解析`,status:"排队中",progress:0,cost:"等待真实解析服务"});setImportOpen(false);notify(`已存入 PocketBase：${form.videoFiles?.length??0} 集片源，解析任务等待处理`)}catch(error){notify(error instanceof Error?error.message:"PocketBase 保存失败")}};
  const replacePoster=async(file:File|null)=>{if(!file||!selected)return;if(!selected.pocketbaseId){notify("该剧尚未连接 PocketBase 记录");return}try{const poster=await preparePoster(file);const stored=await updatePocketBaseDramaPoster(selected.pocketbaseId,poster);const updated=dramaFromPocketBase(stored);setSelected(updated);setDramas(items=>items.map(item=>item.id===selected.id?updated:item));notify("海报已更新并保存到 PocketBase")}catch(error){notify(error instanceof Error?error.message:"海报上传失败")}};
  const persistAnalysis=async(stage:keyof DramaAnalysis,data:unknown)=>{if(!selected?.pocketbaseId)return;const analysis={...(selected.analysis??{}),[stage]:{...(selected.analysis?.[stage]??{status:"completed"}),status:"completed",data,updatedAt:new Date().toISOString()}};try{const stored=await updatePocketBaseDramaAnalysis(selected.pocketbaseId,analysis);const updated=dramaFromPocketBase(stored);setSelected(updated);setDramas(items=>items.map(item=>item.id===updated.id?updated:item));externalPersistAnalysis?.(selected.id,stage,data)}catch(error){notify(error instanceof Error?error.message:"分析结果保存失败")}};
  const retryAnalysis=async(stage:keyof DramaAnalysis)=>{if(!selected?.pocketbaseId)return;const analysis={...(selected.analysis??{}),[stage]:{status:"queued",progress:0,updatedAt:new Date().toISOString()}};try{const stored=await updatePocketBaseDramaAnalysis(selected.pocketbaseId,analysis);const updated=dramaFromPocketBase(stored);setSelected(updated);setDramas(items=>items.map(item=>item.id===updated.id?updated:item));externalRetryAnalysis?.(selected.id,stage);notify(`${stage} 已进入解析队列`)}catch(error){notify(error instanceof Error?error.message:"解析任务创建失败")}};
  const previewAnalysis=(episode:number,start?:number,end?:number)=>{const url=episodeMedia[episode]?.url;if(!url){notify(`第 ${episode} 集没有可播放片源`);return}const fragment=start===undefined?"":`#t=${Math.max(0,start)}${end===undefined?"":`,${Math.max(start,end)}`}`;window.open(`${url}${fragment}`,"_blank","noopener,noreferrer");externalPreviewSource?.({dramaId:selected!.id,episode,start,end})};
  const onRetryAnalysis=(_dramaId:number,stage:keyof DramaAnalysis)=>{void retryAnalysis(stage)};
  const onPersistAnalysis=(_dramaId:number,stage:keyof DramaAnalysis,data:unknown)=>{void persistAnalysis(stage,data)};
  const onPreviewSource=({episode,start,end}:{dramaId:number;episode:number;start?:number;end?:number})=>previewAnalysis(episode,start,end);

  if(!selected)return <section className={styles.workspace}>
    <header className={styles.pageHeader}><div><span className={styles.eyebrow}>短剧智能剧库</span><h1>剧库</h1><p>从剧集理解到可生产资产，用三级解析控制成本并持续沉淀高光与可投放区间。</p></div><div className={styles.headerActions}><button onClick={refresh}>刷新</button><button className={styles.primary} onClick={openImport}>＋ 导入短剧</button></div></header>
    <div className={styles.statStrip}><Metric label="已入库短剧" value={dramas.length}/><Metric label="解析中" value={dramas.filter(d=>d.state==="解析中").length}/><Metric label="高光候选" value={dramas.reduce((sum,item)=>sum+(item.analysis?.highlights?.data?.length??0),0)}/><Metric label="可投放区间" value={dramas.reduce((sum,item)=>sum+(item.analysis?.ranges?.data?.length??0),0)}/></div>
    <div className={styles.filters}><label className={styles.search}>⌕<input value={query} onChange={e=>setQuery(e.target.value)} placeholder="搜索剧名、题材或语种"/></label><select value={genre} onChange={e=>setGenre(e.target.value)}><option>全部题材</option>{[...new Set(dramas.map(d=>d.genre))].map(x=><option key={x}>{x}</option>)}</select><select value={language} onChange={e=>setLanguage(e.target.value)}><option>全部语种</option><option>英语</option><option>德语</option><option>葡萄牙语</option></select><select value={parseState} onChange={e=>setParseState(e.target.value)}><option>全部状态</option><option>解析完成</option><option>解析中</option><option>待解析</option><option>解析失败</option></select><button onClick={()=>{setQuery("");setGenre("全部题材");setLanguage("全部语种");setParseState("全部状态")}}>重置</button><span>{filtered.length} 部短剧</span></div>
    {listState==="loading"?<StateView kind="loading"/>:listState==="error"?<StateView kind="error" onRetry={refresh}/>:filtered.length===0?<StateView kind="empty"/>:<div className={styles.cardGrid}>{filtered.map(d=><article className={styles.dramaCard} key={d.id} onClick={()=>{setSelected(d);setTab("overview")}}><div className={styles.cover} style={{"--accent":d.color} as CSSProperties}>{d.poster&&<img src={d.poster} alt={`${d.cn} 海报`}/>}<span>LUMINA 原创</span><b>{d.cn}</b><small>{d.genre} · {d.episodes} 集</small><i>→</i></div><div className={styles.cardBody}><div className={styles.cardTitle}><div><h2>{d.cn}</h2><p>原名：{d.title} · {d.language}</p></div><span data-state={d.state}>{d.state}</span></div><div className={styles.parseStack}>{d.parse.map(t=><Progress key={t.label} tier={t} color={d.color}/>)}</div><div className={styles.assetCounts}><span><b>{d.people}</b> 人物</span><span><b>{d.ranges}</b> 可投区间</span><span><b>{d.highlights}</b> 高光</span><span><b>{d.drafts}</b> 草稿</span></div></div></article>)}</div>}
    {importOpen&&<ImportModal onClose={()=>setImportOpen(false)} onComplete={finishImport}/>} {toast&&<div className={styles.toast}>✓ {toast}</div>}
  </section>;

  const tabItems:[DetailTab,string,number?][]=[["overview","剧集概览"],["characters","人物关系",selected.analysis?.characters?.data?.length??0],["story","剧情理解"],["highlights","高光候选",selected.analysis?.highlights?.data?.length??0],["ranges","可投放区间",selected.analysis?.ranges?.data?.length??0]];
  return <section className={styles.workspace}><button className={styles.back} onClick={()=>setSelected(null)}>← 返回剧库</button><div className={styles.detailHero}><div className={styles.detailCover} style={{"--accent":selected.color} as CSSProperties}>{selected.poster&&<img src={selected.poster} alt={`${selected.cn} 海报`}/>}<small>LUMINA 原创</small><strong>{selected.cn}</strong><span>{selected.episodes} 集</span></div><div className={styles.heroCopy}><span className={styles.eyebrow}>剧目信息 · 编号 {String(selected.id).padStart(4,"0")}</span><h1>{selected.cn}</h1><h2>原名：{selected.title}</h2><p>{selected.analysis?.story?.data?.[0]?.summary??"真实剧情摘要将在细解析完成后显示。"}</p><div className={styles.heroMeta}><span>{selected.genre}</span><span>{selected.language}</span><span>{selected.episodes} 集</span><span>免费 1–{selected.freeEpisodes} 集</span><span>付费 {selected.freeEpisodes+1}–{selected.episodes} 集</span></div></div><div className={styles.heroActions}><input ref={posterInput} type="file" hidden accept="image/jpeg,image/png,image/webp" onChange={event=>{void replacePoster(event.target.files?.[0]??null);event.currentTarget.value=""}}/><button onClick={()=>posterInput.current?.click()}>▧ {selected.poster?"更换海报":"上传海报"}</button><button onClick={()=>setParseOpen(true)}>⚙ 解析配置</button><button className={styles.primary} onClick={()=>enterFactory("正片剧集拼接")}>进入内容工厂 →</button></div></div>
    <nav className={styles.tabs}>{tabItems.map(([id,label,count])=><button key={id} className={tab===id?styles.active:""} onClick={()=>setTab(id)}>{label}{count!==undefined&&<em>{count}</em>}</button>)}</nav>
    {tab==="overview"&&<Overview drama={selected} notify={notify}/>} {tab==="characters"&&<RealCharacters stage={selected.analysis?.characters} onRetry={()=>onRetryAnalysis?.(selected.id,"characters")} onPersist={data=>onPersistAnalysis?.(selected.id,"characters",data)} notify={notify}/>} {tab==="story"&&<RealStory stage={selected.analysis?.story} availableEpisodes={selected.availableEpisodes??[]} active={activeEpisode} setActive={setActiveEpisode} onRetry={()=>onRetryAnalysis?.(selected.id,"story")} onPersist={data=>onPersistAnalysis?.(selected.id,"story",data)} notify={notify}/>} {tab==="highlights"&&<RealHighlights stage={selected.analysis?.highlights} items={visibleHighlights} episodeMedia={selected.episodeMedia??{}} filter={highlightType} setFilter={setHighlightType} enterFactory={enterFactory} onRetry={()=>onRetryAnalysis?.(selected.id,"highlights")} onPreview={item=>onPreviewSource?.({dramaId:selected.id,episode:item.episode,start:item.start,end:item.end})} notify={notify}/>} {tab==="ranges"&&<RealRanges stage={selected.analysis?.ranges} episodeMedia={selected.episodeMedia??{}} enterFactory={enterFactory} onRetry={()=>onRetryAnalysis?.(selected.id,"ranges")} onPreview={item=>onPreviewSource?.({dramaId:selected.id,episode:item.episodeStart,start:item.start,end:item.end})} notify={notify}/>} {parseOpen&&<ParseConfigModal drama={selected} onClose={()=>setParseOpen(false)} onSave={()=>{onCreateParsingTask?.({id:`CONFIG-${selected.id}-${Date.now()}`,title:`${selected.title} · 解析范围更新`,status:"排队中",progress:0,cost:"预计 ¥18.40"});setParseOpen(false);notify("解析范围已更新，新增任务已进入队列")}}/>} {toast&&<div className={styles.toast}>✓ {toast}</div>}
  </section>;
}

function ImportModal({onClose,onComplete}:{onClose:()=>void;onComplete:(f:ImportForm)=>void}) {
  const [step,setStep]=useState(1);const [form,setForm]=useState(defaultImport);const [files,setFiles]=useState<File[]>([]);const [drag,setDrag]=useState(false);const [error,setError]=useState("");const [progress,setProgress]=useState(0);const input=useRef<HTMLInputElement>(null);const posterInput=useRef<HTMLInputElement>(null);
  const patch=(k:keyof ImportForm,v:string)=>setForm(f=>({...f,[k]:v}));const addFiles=(list:FileList|null)=>{const next=Array.from(list??[]);if(!next.length)return;const invalid=next.filter(file=>!supportedDramaFile(file.name));if(invalid.length){setError(`不支持 ${invalid.map(file=>file.name).join("、")}；仅可上传 MP4 或 MOV 视频（ZIP 暂不支持直接播放）`);return}setFiles(v=>[...v,...next]);setError("")};
  const drop=(e:DragEvent)=>{e.preventDefault();setDrag(false);addFiles(e.dataTransfer.files)};
  const next=()=>{if(step===1&&error)return;if(step===1&&!files.length){setError("请先上传至少一集 MP4 或 MOV 正片视频");return}if(step===2&&(!form.title.trim()||!form.cn.trim())){setError("请填写中英文剧名");return}setError("");if(step<3)setStep(step+1);else{setStep(4);const recognized=recognizeEpisodeFiles(files.map(file=>file.name),1);const completedForm={...form,uploadedEpisodes:recognized.map(value=>value.episode),videoFiles:recognized.map(value=>({episode:value.episode,file:files.find(file=>file.name===value.name)!}))};let n=0;const timer=window.setInterval(()=>{n+=20;setProgress(n);if(n>=100){window.clearInterval(timer);window.setTimeout(()=>onComplete(completedForm),450)}},180)}};
  return <div className={styles.modalMask} onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><section className={styles.modalWide}><header><div><span className={styles.eyebrow}>导入剧目</span><h2>导入短剧</h2></div><button onClick={onClose}>×</button></header><div className={styles.stepper}>{["上传剧集","基础信息","解析范围","创建任务"].map((s,i)=><div className={i+1<=step?styles.done:""} key={s}><i>{i+1<step?"✓":i+1}</i><span>{s}</span></div>)}</div><div className={styles.modalBody}>
    {step===1&&<><div className={`${styles.uploadZone} ${drag?styles.drag:""}`} onDragOver={e=>{e.preventDefault();setDrag(true)}} onDragLeave={()=>setDrag(false)} onDrop={drop} onClick={()=>input.current?.click()}><input ref={input} type="file" hidden multiple accept=".mp4,.mov,video/mp4,video/quicktime" onChange={e=>{addFiles(e.target.files);e.currentTarget.value=""}}/><strong>↑</strong><h3>拖拽剧集视频到这里</h3><p>支持 MP4、MOV；完成导入后视频会真实保存到 PocketBase，建议按“剧名_EP01”命名。</p><button type="button">选择文件</button></div>{files.length>0&&<div className={styles.fileList}>{files.map((f,i)=><div key={`${f.name}-${i}`}><span>▣</span><b>{f.name}</b><small>{(f.size/1024/1024).toFixed(1)} MB · 待上传 PocketBase</small><button onClick={event=>{event.stopPropagation();setFiles(v=>v.filter((_,x)=>x!==i));setError("")}}>移除</button></div>)}</div>}</>}
    {step===2&&<div className={styles.formGrid}>
      <label className={`${styles.full} ${styles.posterUpload}`}>
        <span>短剧海报</span>
        <input ref={posterInput} type="file" hidden accept="image/jpeg,image/png,image/webp" onChange={async event=>{
          const inputElement=event.currentTarget;
          const file=inputElement.files?.[0];
          if(!file)return;
          try{patch("poster",await preparePoster(file));setError("")}
          catch(problem){setError(problem instanceof Error?problem.message:"海报上传失败")}
          finally{inputElement.value=""}
        }}/>
        {form.poster?<><img src={form.poster} alt="短剧海报预览"/><div><b>海报已就绪</b><small>将作为剧库缩略图与详情封面</small><button type="button" onClick={()=>posterInput.current?.click()}>更换海报</button><button type="button" onClick={()=>patch("poster","")}>移除</button></div></>:<button type="button" onClick={()=>posterInput.current?.click()}>＋ 上传 JPG / PNG / WebP 海报</button>}
      </label>
      <label><span>英文剧名 *</span><input value={form.title} onChange={e=>patch("title",e.target.value)} placeholder="Goodbye, My Billionaire Husband"/></label>
      <label><span>中文剧名 *</span><input value={form.cn} onChange={e=>patch("cn",e.target.value)} placeholder="再见，我的亿万富翁丈夫"/></label>
      <label><span>题材</span><select value={form.genre} onChange={e=>patch("genre",e.target.value)}><option>都市情感</option><option>豪门甜宠</option><option>狼人奇幻</option><option>女性复仇</option></select></label>
      <label><span>语种</span><select value={form.language} onChange={e=>patch("language",e.target.value)}><option>英语</option><option>德语</option><option>葡萄牙语</option><option>西班牙语</option></select></label>
      <label><span>总集数</span><input type="number" value={form.episodes} onChange={e=>patch("episodes",e.target.value)}/></label>
      <label><span>免费集数</span><input type="number" value={form.freeEpisodes} onChange={e=>patch("freeEpisodes",e.target.value)}/></label>
      <label className={styles.full}><span>版权状态</span><select value={form.copyright} onChange={e=>patch("copyright",e.target.value)}><option>已获得版权／内部自制</option><option>仅限分析</option><option>待补充授权证明</option></select></label>
    </div>}
    {step===3&&<div className={styles.parseChoices}><article><i>01</i><div><h3>粗解析</h3><p>低频抽帧、ASR、OCR、剧情摘要与人物初识别。</p></div><label>覆盖前 <input value={form.coarse} onChange={e=>patch("coarse",e.target.value)}/> 集</label></article><article><i>02</i><div><h3>重点集细解析</h3><p>完整对白、人物关系、剧情理解与慢热问题判断。</p></div><label>重点集 <input value={form.detail} onChange={e=>patch("detail",e.target.value)}/></label></article><article><i>03</i><div><h3>高光区间精解析</h3><p>仅对候选片段做帧级、镜头级、音画级分析。</p></div><select value={form.precision} onChange={e=>patch("precision",e.target.value)}><option>自动发现候选</option><option>暂不执行</option><option>全部候选自动精析</option></select></article><aside>预计先处理 {form.coarse} 集粗解析、重点集 {form.detail}；精解析会在发现候选后启动，可随时在详情页调整。</aside></div>}
    {step===4&&<div className={styles.taskCreating}><span className={progress<100?styles.spinner:""}>{progress>=100?"✓":""}</span><h3>{progress<100?"正在创建上传与解析任务":"任务创建成功"}</h3><div><i style={{width:`${progress}%`}}/></div><b>{progress}%</b><p>{progress<40?"正在校验剧集文件…":progress<80?"正在创建三级解析队列…":"正在写入剧库…"}</p></div>}{error&&<div className={styles.formError}>! {error}</div>}
  </div>{step<4&&<footer><button onClick={step===1?onClose:()=>setStep(step-1)}>{step===1?"取消":"上一步"}</button><button className={styles.primary} onClick={next}>{step===3?"确认导入并解析":"下一步"}</button></footer>}</section></div>;
}

function ParseConfigModal({drama,onClose,onSave}:{drama:Drama;onClose:()=>void;onSave:()=>void}) { const [coarse,setCoarse]=useState(String(drama.freeEpisodes));const [detail,setDetail]=useState("1-5, 8, 12");const [auto,setAuto]=useState(true);return <div className={styles.modalMask}><section className={styles.modal}><header><div><span className={styles.eyebrow}>PARSE CONFIG</span><h2>解析配置</h2><p>{drama.cn} · 默认值均可调整</p></div><button onClick={onClose}>×</button></header><div className={styles.configList}><label><span><b>粗解析范围</b><small>建议覆盖全部免费集</small></span><input value={coarse} onChange={e=>setCoarse(e.target.value)}/><em>集</em></label><label><span><b>重点集细解析</b><small>支持范围与单集混填</small></span><input value={detail} onChange={e=>setDetail(e.target.value)}/></label><label><span><b>候选区间自动精析</b><small>新发现高光自动加入任务队列</small></span><button className={auto?styles.switchOn:styles.switch} onClick={()=>setAuto(!auto)}><i/></button></label></div><div className={styles.taskStatus}><b>任务影响</b><span>新增粗解析 {Math.max(0,Number(coarse)-drama.freeEpisodes)} 集</span><span>预计新增成本 ¥18.40</span><span>预计 26 分钟完成</span></div><footer><button onClick={onClose}>取消</button><button className={styles.primary} onClick={onSave}>保存并更新任务</button></footer></section></div>; }

function Overview({drama,notify}:{drama:Drama;notify:(s:string)=>void}) {
  const [playing,setPlaying]=useState<number|null>(null);const media=drama.episodeMedia??{};const episodes=Array.from({length:drama.episodes},(_,i)=>i+1);const active=playing?media[playing]:undefined;
  const statusLabel=(item?:FactoryEpisodeMedia)=>{if(!item)return "等待视频";if(item.analysisStatus==="completed")return "粗解析完成";if(item.analysisStatus==="running"||item.analysisStatus==="processing")return `粗解析中${item.analysisProgress?` ${item.analysisProgress}%`:""}`;if(item.analysisStatus==="failed")return `解析失败${item.analysisError?`：${item.analysisError}`:""}`;if(item.analysisStatus==="queued")return "解析排队中";return "待解析"};
  return <div className={styles.detailGrid}><main><section className={styles.panel}><div className={styles.panelHead}><div><span className={styles.eyebrow}>三级解析</span><h2>三级解析进度</h2></div><span className={styles.confidence}>PocketBase 实时状态</span></div><div className={styles.tierCards}>{drama.parse.map((tier,index)=><article key={tier.label}><span>0{index+1}</span><h3>{tier.label}</h3><strong>{tier.progress}%</strong><i><em style={{width:`${tier.progress}%`,background:drama.color}}/></i><small>{tier.scope}</small></article>)}</div></section><section className={styles.panel}><div className={styles.panelHead}><div><h2>剧集与解析状态</h2><p>免费 1–{drama.freeEpisodes} 集 · 付费 {drama.freeEpisodes+1}–{drama.episodes} 集</p></div><span className={styles.confidence}>正片已获取 {Object.keys(media).length} / {drama.episodes}</span></div><div className={styles.episodeTable}><div><b>集数</b><b>范围</b><b>视频</b><b>解析状态</b><b>操作</b></div>{episodes.map(number=>{const item=media[number];return <div key={number} data-missing={!item||undefined}><span>第 {number} 集</span><span data-paid={number>drama.freeEpisodes}>{number<=drama.freeEpisodes?"免费":"付费"}</span><span>{item?`${item.name}${item.duration?` · ${formatTime(item.duration)}`:" · 时长待探测"}`:"未获取"}</span><span title={item?.analysisError}><i data-status={!item?"missing":item.analysisStatus==="completed"?"done":item.analysisStatus==="failed"?"missing":"working"}/>{statusLabel(item)}</span><button disabled={!item?.url} onClick={()=>{setPlaying(number);notify(`正在播放第 ${number} 集真实片源`)}}>{item?.url?"▶ 播放":"暂无视频"}</button></div>})}</div></section><section className={styles.panel}><h2>真实资产概览</h2><div className={styles.overviewMetrics}><Metric label="已获取正片" value={`${Object.keys(media).length} 集`} hint="PocketBase 视频记录"/><Metric label="粗解析完成" value={`${Object.values(media).filter(item=>item.analysisStatus==="completed").length} 集`} hint="按剧集任务状态统计"/><Metric label="人物结果" value={drama.analysis?.characters?.data?.length??0} hint="真实解析结果"/><Metric label="高光 / 区间" value={`${drama.analysis?.highlights?.data?.length??0} / ${drama.analysis?.ranges?.data?.length??0}`} hint="真实解析结果"/></div></section></main><aside>{active?.url?<section className={`${styles.panel} ${styles.realPlayer}`}><div className={styles.panelHead}><div><h2>第 {playing} 集预览</h2><p>{active.name}</p></div><button onClick={()=>setPlaying(null)}>×</button></div><video key={active.url} controls autoPlay preload="metadata" src={active.url} onError={()=>notify("视频加载失败，请检查 PocketBase 文件地址")}/>{active.duration&&<small>片源时长 {formatTime(active.duration)}</small>}</section>:<section className={`${styles.panel} ${styles.analysisState}`}><span>▶</span><h2>剧集预览</h2><p>点击有真实 PocketBase 文件地址的剧集开始播放。</p></section>}<section className={styles.costNote}><span>数据来源</span><b>PocketBase 实时记录</b><p>视频、时长、解析状态与分析结果均由持久化记录提供；缺失字段明确显示为等待或未获取。</p></section></aside></div>;
}

function Characters({notify}:{notify:(s:string)=>void}) { const [active,setActive]=useState(0);const p=people[active];return <div className={styles.peopleLayout}><section className={styles.panel}><div className={styles.panelHead}><div><h2>人物关系图</h2><p>点击人物节点查看身份、识别证据与关系变化</p></div><span className={styles.confidence}>人脸聚合置信度 94%</span></div><div className={styles.relationGraph}><svg viewBox="0 0 800 290" aria-hidden="true"><line x1="160" y1="145" x2="350" y2="70"/><line x1="160" y1="145" x2="350" y2="220"/><line x1="350" y1="70" x2="640" y2="145"/><line x1="350" y1="220" x2="640" y2="145"/></svg>{people.map((x,i)=><button key={x.n} className={`${styles.graphNode} ${active===i?styles.selectedNode:""}`} style={{"--x":["12%","43%","43%","78%"][i],"--y":["50%","25%","76%","50%"][i]} as CSSProperties} onClick={()=>setActive(i)}><span data-tone={i}>{x.c}</span><b>{x.n}</b><small>{x.r.split(" · ")[0]}</small></button>)}</div></section><div className={styles.characterDetail}><section className={styles.panel}><div className={styles.characterHero}><div className={styles.avatar} data-tone={active}>{p.c}<i>✓</i></div><div><span className={styles.eyebrow}>CHARACTER NODE</span><h2>{p.n}</h2><b>{p.r}</b></div><em>{p.status}</em></div><p>{p.note}</p><dl><div><dt>出场范围</dt><dd>{p.episodes}</dd></div><div><dt>人脸置信度</dt><dd>{p.confidence}%</dd></div><div><dt>视觉锚点</dt><dd>{p.tags}</dd></div><div><dt>核心关系</dt><dd>{p.rel}</dd></div></dl><button onClick={()=>notify(`${p.n} 已标记为待人工复核`)}>标记人工复核</button></section><section className={styles.panel}><h2>关系变化时间线</h2><div className={styles.relationTimeline}><div><i/>第 1 集 · 婚姻破裂，关系转为敌对</div><div><i/>第 5 集 · 身份线索出现，立场开始松动</div><div><i/>第 8 集 · 公开保护，关系进入暧昧阶段</div></div></section></div><section className={styles.panel}><h2>核心人物卡</h2><div className={styles.peopleGrid}>{people.map((x,i)=><article key={x.n} onClick={()=>setActive(i)}><div className={styles.avatar} data-tone={i}>{x.c}<i>✓</i></div><h3>{x.n}</h3><b>{x.r}</b><p>{x.tags}</p><small>{x.rel}</small></article>)}</div></section></div>; }

function Story({active,setActive,notify}:{active:number;setActive:(n:number)=>void;notify:(s:string)=>void}) { const [editing,setEditing]=useState(false);const [summary,setSummary]=useState("Elena 被当众驱逐时，律师带着股权证明出现。Adrian 第一次意识到这场离婚可能是一个巨大错误。");const [suggestion,setSuggestion]=useState("宴会寒暄与配角重复嘲讽，信息增量较低。建议压缩至 12 秒，保留女主观察出口与手握旧项链的镜头。");const save=()=>{setEditing(false);notify(`第 ${active} 集剧情理解与剪辑建议已保存`)};return <div className={styles.storyLayout}><aside className={styles.episodeRail}><div><h2>剧集</h2><span>已细析 9 集</span></div>{Array.from({length:15},(_,i)=>i+1).map(n=><button key={n} className={active===n?styles.active:""} onClick={()=>setActive(n)}><i>{String(n).padStart(2,"0")}</i><span><b>第 {n} 集</b><small>{n<=5?"重点集细解析":n<=9?"用户指定重点集":"仅粗解析"}</small></span><em>{n<=9?"✓":"○"}</em></button>)}</aside><main className={styles.storyMain}><section className={styles.storyTitle}><div><span className={styles.eyebrow}>EPISODE {String(active).padStart(2,"0")}</span><h1>{active===3?"宴会上的第二重身份":"隐藏身份线继续推进"}</h1>{editing?<textarea value={summary} onChange={e=>setSummary(e.target.value)}/>:<p>{summary}</p>}</div><div className={styles.storyActions}><span>{active<=9?"重点集细解析":"粗解析"}</span><button onClick={()=>editing?save():setEditing(true)}>{editing?"保存修改":"编辑理解"}</button></div></section><div className={styles.storyCards}><article><small>核心事件</small><h3>股权书进入宴会，女主身份第一次获得公开证明</h3><p>事件完成“压制—证据—反转”的闭环，可独立剪成一段连贯投放剧情。</p></article><article><small>人物关系变化</small><h3>Elena × Adrian：敌对 → 动摇</h3><p>男主开始保护女主，但动机仍不明确，为后续复合线埋下伏笔。</p></article><article><small>冲突、情绪与爽点</small><div className={styles.emotionLine}><i/><i/><i/><i/><i/></div><p>屈辱 82 · 紧张 76 · 爽感 94</p></article><article><small>伏笔、高潮与付费卡点</small><h3>律师未公布的第二份遗嘱</h3><p>建议在律师打开文件、念出女主名字前卡断。</p></article></div><section className={styles.compress}><div><span>可压缩铺垫</span><b>01:14–02:06</b></div>{editing?<textarea value={suggestion} onChange={e=>setSuggestion(e.target.value)}/>:<p>{suggestion}</p>}<button onClick={()=>{if(editing)save();else notify("剪辑建议已加入可投放区间评估")}}>{editing?"保存剪辑建议":"标记为剪辑建议"}</button></section></main></div>; }

function Highlights({items,filter,setFilter,enterFactory,notify}:{items:typeof highlights;filter:string;setFilter:(v:string)=>void;enterFactory:(m:string,id?:number)=>void;notify:(s:string)=>void}) { const [detail,setDetail]=useState<(typeof highlights)[number]|null>(null);const [selected,setSelected]=useState<number[]>([]);const [favorites,setFavorites]=useState<number[]>([2]);const toggle=(id:number)=>setSelected(v=>v.includes(id)?v.filter(x=>x!==id):[...v,id]);return <><div className={styles.subToolbar}><div><h2>高光候选</h2><p>候选由粗／细解析发现，经区间精解析验证留客能力与卡断点。</p></div><div className={styles.batchActions}>{selected.length>0&&<><b>已选 {selected.length} 个</b><button onClick={()=>{setFavorites(v=>[...new Set([...v,...selected])]);notify(`已收藏 ${selected.length} 个高光候选`)}}>批量收藏</button><button className={styles.primary} onClick={()=>enterFactory("正片剧集拼接",selected[0])}>批量进入工厂</button></>}<select value={filter} onChange={e=>setFilter(e.target.value)}>{["全部类型",...new Set(highlights.map(h=>h.category))].map(x=><option key={x}>{x}</option>)}</select></div></div>{items.length===0?<StateView kind="empty"/>:<div className={styles.highlightGrid}>{items.map(h=><article key={h.id} className={selected.includes(h.id)?styles.selectedCard:""}><label className={styles.check}><input type="checkbox" checked={selected.includes(h.id)} onChange={()=>toggle(h.id)}/><span/></label><button className={styles.favorite} data-active={favorites.includes(h.id)} onClick={()=>setFavorites(v=>v.includes(h.id)?v.filter(x=>x!==h.id):[...v,h.id])}>♥</button><div className={styles.highlightPreview} style={{"--accent":h.color} as CSSProperties} onClick={()=>setDetail(h)}><span>{h.episode} · {h.time}</span><button>▶</button><em>{h.category}</em></div><div className={styles.highlightBody}><span className={styles.eyebrow}>{h.event}</span><h2>{h.title}</h2><p>{h.emotion}</p><div className={styles.scoreRow}><span><small>留客能力</small><b>{h.retention}</b></span><span><small>剧透风险</small><b>{h.spoiler}</b></span><span><small>伏笔充分度</small><b>{h.setup}</b></span></div><div className={styles.cardButtons}><button onClick={()=>setDetail(h)}>查看详情</button><button className={styles.primary} onClick={()=>enterFactory("正片剧集拼接",h.id)}>进入剧集拼接 →</button></div></div></article>)}</div>}{detail&&<div className={styles.drawerMask} onClick={()=>setDetail(null)}><aside className={styles.drawer} onClick={e=>e.stopPropagation()}><header><div><span className={styles.eyebrow}>HIGHLIGHT DETAIL</span><h2>{detail.title}</h2></div><button onClick={()=>setDetail(null)}>×</button></header><div className={styles.drawerVideo} style={{"--accent":detail.color} as CSSProperties}><button>▶</button><span>{detail.episode} · {detail.time}</span></div><div className={styles.drawerContent}><div className={styles.scoreRow}><span><small>留客能力</small><b>{detail.retention}</b></span><span><small>剧透风险</small><b>{detail.spoiler}</b></span><span><small>伏笔充分度</small><b>{detail.setup}</b></span></div><section><small>情绪与戏剧事件</small><h3>{detail.event} · {detail.emotion}</h3></section><section><small>精解析证据</small><p>{detail.evidence}</p></section><section><small>推荐卡断点</small><h3>{detail.cut}</h3></section></div><footer><button onClick={()=>setFavorites(v=>v.includes(detail.id)?v.filter(x=>x!==detail.id):[...v,detail.id])}>{favorites.includes(detail.id)?"取消收藏":"收藏高光"}</button><button className={styles.primary} onClick={()=>enterFactory("正片剧集拼接",detail.id)}>进入剧集拼接</button></footer></aside></div>}</>; }

function Ranges({enterFactory,notify}:{enterFactory:(m:string,id?:number)=>void;notify:(s:string)=>void}) { const [mode,setMode]=useState("全部模式");const [selected,setSelected]=useState<number[]>([]);const shown=mode==="全部模式"?ranges:ranges.filter(r=>r.modes.includes(mode));return <><div className={styles.subToolbar}><div><h2>可投放区间</h2><p>已验证剧情连续性、可剪辑性与模式适配，可直接作为生产输入。</p></div><div className={styles.batchActions}>{selected.length>0&&<><b>已选 {selected.length} 个</b><button onClick={()=>notify("所选区间已加入对比")}>加入对比</button></>}<select value={mode} onChange={e=>setMode(e.target.value)}><option>全部模式</option><option>正片剧集拼接</option><option>正片剧集解说</option><option>外搭钩子+本剧正片</option></select></div></div>{shown.length===0?<StateView kind="empty"/>:<div className={styles.rangeList}>{shown.map(r=><article key={r.id} className={selected.includes(r.id)?styles.selectedCard:""}><label className={styles.rangeCheck}><input type="checkbox" checked={selected.includes(r.id)} onChange={()=>setSelected(v=>v.includes(r.id)?v.filter(x=>x!==r.id):[...v,r.id])}/></label><div className={styles.rangeNo}>0{r.id}<span>{r.episodes}</span><small>{r.duration}</small></div><div className={styles.rangeCopy}><h2>{r.title}</h2><p>{r.summary}</p><div className={styles.rangeMeta}><span>人物 <b>{r.people}</b></span><span>情绪曲线 <b>{r.curve}</b></span><span>付费卡点 <b>{r.paywall}</b></span></div><div className={styles.modeTags}>{r.modes.map(m=><span key={m}>{m}</span>)}</div><div className={styles.inlineActions}><button onClick={()=>notify(`正在预览${r.episodes}`)}>▶ 预览</button><button onClick={()=>notify("区间起止点已打开，可拖动微调")}>调整区间</button><button onClick={()=>notify("已保存为可复用剧情资产")}>收藏区间</button></div></div><div className={styles.rangeScores}><span><small>剧情连续性</small><b>{r.continuity}</b><i><em style={{width:`${r.continuity}%`}}/></i></span><span><small>可剪辑性</small><b>{r.editability}</b><i><em style={{width:`${r.editability}%`}}/></i></span><select aria-label="选择生产模式" defaultValue={r.modes[0]}>{r.modes.map(m=><option key={m}>{m}</option>)}</select><button className={styles.primary} onClick={e=>{const select=e.currentTarget.previousElementSibling as HTMLSelectElement;enterFactory(select.value,r.id)}}>进入内容工厂 →</button></div></article>)}</div>}</>; }

function AnalysisGate<T>({stage,label,onRetry,children}:{stage?:AnalysisStage<T>;label:string;onRetry:()=>void;children:(data:T)=>ReactNode}) {
  const status=stage?.status??"idle";
  if(status==="completed"&&stage?.data!==undefined)return <>{children(stage.data)}</>;
  const copy=status==="queued"?["已进入解析队列","任务开始后会自动更新此页面"]:status==="processing"?[`${label}处理中`,`${Math.max(0,Math.min(100,stage?.progress??0))}% · 结果尚未生成`]:status==="failed"?[`${label}失败`,stage?.error||"解析服务未返回可用结果"]:[`暂无${label}结果`,"请先上传真实片源并创建解析任务"];
  return <section className={`${styles.panel} ${styles.analysisState}`} data-status={status}><span>{status==="failed"?"!":status==="processing"||status==="queued"?"…":"○"}</span><h2>{copy[0]}</h2><p>{copy[1]}</p>{(status==="failed"||status==="idle")&&<button onClick={onRetry}>{status==="failed"?"重新解析":"创建解析任务"}</button>}</section>;
}

function RealCharacters({stage,onRetry,onPersist,notify}:{stage?:AnalysisStage<CharacterResult[]>;onRetry:()=>void;onPersist:(data:CharacterResult[])=>void;notify:(s:string)=>void}) {
  const [activeId,setActiveId]=useState<number|null>(null);
  return <AnalysisGate stage={stage} label="人物关系" onRetry={onRetry}>{items=>{if(items.length===0)return <section className={`${styles.panel} ${styles.analysisState}`}><span>○</span><h2>未识别到人物</h2><p>解析已完成，但没有足够证据形成角色聚类。</p></section>;const active=items.find(item=>item.id===activeId)??items[0];return <div className={styles.peopleLayout}><section className={styles.panel}><div className={styles.panelHead}><div><h2>人物识别结果</h2><p>所有人物、关系与证据均来自当前短剧解析结果</p></div><span className={styles.confidence}>{stage?.updatedAt?`更新于 ${new Date(stage.updatedAt).toLocaleString()}`:"解析完成"}</span></div><div className={styles.peopleGrid}>{items.map((person,index)=><article key={person.id} className={person.id===active.id?styles.selectedCard:""} onClick={()=>setActiveId(person.id)}><div className={styles.avatar} data-tone={index%4}>{person.name.split(/\s+/).map(v=>v[0]).join("").slice(0,2)}</div><h3>{person.name}</h3><b>{person.role||"角色待确认"}</b><p>{person.episodes.length?`出场：第 ${person.episodes.join("、")} 集`:"未定位出场集"}</p><small>{person.confidence===undefined?"置信度未提供":`识别置信度 ${Math.round(person.confidence*100)/100}%`}</small></article>)}</div></section><section className={styles.panel}><h2>{active.name}</h2><p>{active.evidence?.length?active.evidence.join("；"):"解析结果未提供人物证据"}</p><dl className={styles.resultFacts}><div><dt>角色</dt><dd>{active.role||"待确认"}</dd></div><div><dt>别名</dt><dd>{active.aliases?.join("、")||"无"}</dd></div><div><dt>关系</dt><dd>{active.relationships?.length??0} 条</dd></div></dl><div className={styles.relationTimeline}>{active.relationships?.map(rel=><div key={`${rel.targetId}-${rel.label}-${rel.episode??0}`}><i/>第 {rel.episode??"?"} 集 · {rel.label}{rel.evidence?` · ${rel.evidence}`:""}</div>)}</div><button onClick={()=>{onPersist(items.map(item=>item.id===active.id?{...item,role:item.role||"待人工复核"}:item));notify("人工复核状态已提交")}}>标记人工复核</button></section></div>}}</AnalysisGate>;
}

function RealStory({stage,availableEpisodes,active,setActive,onRetry,onPersist,notify}:{stage?:AnalysisStage<StoryResult[]>;availableEpisodes:number[];active:number;setActive:(n:number)=>void;onRetry:()=>void;onPersist:(data:StoryResult[])=>void;notify:(s:string)=>void}) {
  const [draft,setDraft]=useState("");
  return <AnalysisGate stage={stage} label="剧情理解" onRetry={onRetry}>{items=>{if(items.length===0)return <section className={`${styles.panel} ${styles.analysisState}`}><span>○</span><h2>没有剧情理解结果</h2><p>任务已完成，但未产出可用的单集摘要。</p></section>;const current=items.find(item=>item.episode===active)??items[0];return <div className={styles.storyLayout}><aside className={styles.episodeRail}><div><h2>已解析剧集</h2><span>{items.length} 集</span></div>{availableEpisodes.map(episode=>{const result=items.find(item=>item.episode===episode);return <button key={episode} disabled={!result} className={current.episode===episode?styles.active:""} onClick={()=>result&&setActive(episode)}><i>{String(episode).padStart(2,"0")}</i><span><b>第 {episode} 集</b><small>{result?"剧情理解完成":"等待解析"}</small></span><em>{result?"✓":"○"}</em></button>})}</aside><main className={styles.storyMain}><section className={styles.storyTitle}><div><span className={styles.eyebrow}>第 {current.episode} 集</span><h1>{current.title||`第 ${current.episode} 集`}</h1><textarea value={draft||current.summary} onChange={e=>setDraft(e.target.value)}/></div><div className={styles.storyActions}><span>真实解析结果</span><button onClick={()=>{const next=items.map(item=>item.episode===current.episode?{...item,summary:draft||current.summary}:item);onPersist(next);setDraft("");notify("剧情理解修改已提交")}}>保存修改</button></div></section><div className={styles.storyCards}><article><small>核心事件</small>{current.coreEvents?.length?<ul>{current.coreEvents.map(event=><li key={event}>{event}</li>)}</ul>:<p>未产出核心事件</p>}</article><article><small>人物关系变化</small>{current.relationshipChanges?.length?<ul>{current.relationshipChanges.map(change=><li key={change}>{change}</li>)}</ul>:<p>未产出关系变化</p>}</article><article><small>情绪信号</small>{current.emotions?.length?<p>{current.emotions.map(x=>`${x.label} ${x.score}`).join(" · ")}</p>:<p>未产出情绪分数</p>}</article><article><small>伏笔与卡点</small>{current.foreshadowing?.length?<ul>{current.foreshadowing.map(x=><li key={x}>{x}</li>)}</ul>:<p>未产出伏笔</p>}</article></div>{current.editSuggestion&&<section className={styles.compress}><div><span>可压缩铺垫</span><b>{formatTime(current.editSuggestion.start)}–{formatTime(current.editSuggestion.end)}</b></div><p>{current.editSuggestion.reason}</p></section>}</main></div>}}</AnalysisGate>;
}

const formatTime=(seconds:number)=>`${String(Math.floor(seconds/60)).padStart(2,"0")}:${String(Math.max(0,Math.floor(seconds%60))).padStart(2,"0")}`;

function ClipFirstFrame({media,start,label}:{media?:FactoryEpisodeMedia;start:number;label:string}) {
  const videoRef=useRef<HTMLVideoElement>(null);const [ready,setReady]=useState(false);const [failed,setFailed]=useState(false);
  useEffect(()=>{setReady(false);setFailed(false)},[media?.url,start]);
  if(!media?.url)return <div className={styles.frameUnavailable}>首帧不可用</div>;
  return <><video ref={videoRef} className={styles.clipFirstFrame} muted playsInline preload="auto" src={`${media.url}#t=${Math.max(0,start).toFixed(3)}`} aria-label={label} onLoadedMetadata={event=>{const target=event.currentTarget;const safeStart=Math.min(Math.max(0,start),Math.max(0,(target.duration||start)-.04));if(Math.abs(target.currentTime-safeStart)>.03)target.currentTime=safeStart}} onLoadedData={()=>setReady(true)} onSeeked={()=>setReady(true)} onError={()=>setFailed(true)}/>{!ready&&!failed&&<div className={styles.frameUnavailable}>正在提取首帧…</div>}{failed&&<div className={styles.frameUnavailable}>首帧加载失败</div>}</>;
}

function RealHighlights({stage,items,episodeMedia,filter,setFilter,enterFactory,onRetry,onPreview,notify}:{stage?:AnalysisStage<HighlightResult[]>;items:HighlightResult[];episodeMedia:Record<number,FactoryEpisodeMedia>;filter:string;setFilter:(v:string)=>void;enterFactory:(m:string,id?:number)=>void;onRetry:()=>void;onPreview:(item:HighlightResult)=>void;notify:(s:string)=>void}) {
  const all=stage?.data??[];const [selected,setSelected]=useState<number[]>([]);return <AnalysisGate stage={stage} label="高光候选" onRetry={onRetry}>{()=> <><div className={styles.subToolbar}><div><h2>高光候选</h2><p>仅展示解析服务返回且带有真实时间码的候选片段。</p></div><div className={styles.batchActions}>{selected.length>0&&<button className={styles.primary} onClick={()=>enterFactory("正片剧集拼接",selected[0])}>所选进入工厂</button>}<select value={filter} onChange={e=>setFilter(e.target.value)}>{["全部类型",...new Set(all.map(item=>item.category))].map(x=><option key={x}>{x}</option>)}</select></div></div>{items.length===0?<section className={`${styles.panel} ${styles.analysisState}`}><h2>当前筛选无结果</h2><p>请调整高光类型筛选。</p></section>:<div className={styles.highlightGrid}>{items.map(item=><article key={item.id}><label className={styles.check}><input type="checkbox" checked={selected.includes(item.id)} onChange={()=>setSelected(v=>v.includes(item.id)?v.filter(id=>id!==item.id):[...v,item.id])}/><span/></label><div className={styles.highlightPreview} onClick={()=>onPreview(item)}><ClipFirstFrame media={episodeMedia[item.episode]} start={item.start} label={`第 ${item.episode} 集片段首帧`}/><span>第 {item.episode} 集 · {formatTime(item.start)}–{formatTime(item.end)}</span><button aria-label="预览真实片源">▶</button><em>{item.category}</em></div><div className={styles.highlightBody}><span className={styles.eyebrow}>{item.event||"高光事件"}</span><h2>{item.title}</h2><p>{item.evidence||"解析未提供证据说明"}</p><div className={styles.scoreRow}><span><small>留客能力</small><b>{item.retention??"—"}</b></span><span><small>剧透风险</small><b>{item.spoilerRisk??"—"}</b></span><span><small>伏笔充分度</small><b>{item.setup??"—"}</b></span></div><div className={styles.cardButtons}><button onClick={()=>onPreview(item)}>预览片源</button><button className={styles.primary} onClick={()=>enterFactory("正片剧集拼接",item.id)}>进入剧集拼接 →</button></div></div></article>)}</div>}</>}</AnalysisGate>;
}

function RealRanges({stage,episodeMedia,enterFactory,onRetry,onPreview}:{stage?:AnalysisStage<RangeResult[]>;episodeMedia:Record<number,FactoryEpisodeMedia>;enterFactory:(m:string,id?:number)=>void;onRetry:()=>void;onPreview:(item:RangeResult)=>void;notify:(s:string)=>void}) {
  const [mode,setMode]=useState("全部模式");const items=stage?.data??[];const shown=mode==="全部模式"?items:items.filter(item=>item.modes.includes(mode));return <AnalysisGate stage={stage} label="可投放区间" onRetry={onRetry}>{()=> <><div className={styles.subToolbar}><div><h2>可投放区间</h2><p>区间集数、时间码与评分均直接来自解析结果。</p></div><select value={mode} onChange={e=>setMode(e.target.value)}>{["全部模式",...new Set(items.flatMap(item=>item.modes))].map(x=><option key={x}>{x}</option>)}</select></div>{shown.length===0?<section className={`${styles.panel} ${styles.analysisState}`}><h2>当前筛选无结果</h2><p>请调整生产模式筛选。</p></section>:<div className={styles.rangeList}>{shown.map(item=><article key={item.id}><div className={styles.rangeThumb}><ClipFirstFrame media={episodeMedia[item.episodeStart]} start={item.start} label={`第 ${item.episodeStart} 集区间首帧`}/><button type="button" aria-label="预览该片段" onClick={()=>onPreview(item)}>▶</button></div><div className={styles.rangeNo}>{String(item.id).padStart(2,"0")}<span>第 {item.episodeStart}–{item.episodeEnd} 集</span><small>{formatTime(Math.max(0,item.end-item.start))}</small></div><div className={styles.rangeCopy}><h2>{item.title}</h2><p>{item.summary}</p><div className={styles.modeTags}>{item.modes.map(value=><span key={value}>{value}</span>)}</div><div className={styles.inlineActions}><button onClick={()=>onPreview(item)}>▶ 预览真实片源</button></div></div><div className={styles.rangeScores}><span><small>剧情连续性</small><b>{item.continuity??"—"}</b></span><span><small>可剪辑性</small><b>{item.editability??"—"}</b></span><select aria-label="选择生产模式" defaultValue={item.modes[0]}>{item.modes.map(value=><option key={value}>{value}</option>)}</select><button className={styles.primary} onClick={event=>enterFactory((event.currentTarget.previousElementSibling as HTMLSelectElement).value,item.id)}>进入内容工厂 →</button></div></article>)}</div>}</>}</AnalysisGate>;
}

export default DramaLibraryWorkspace;
